import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _load_document_bytes(source: Any) -> bytes:
    if isinstance(source, (bytes, bytearray)):
        return bytes(source)
    if isinstance(source, str):
        if os.path.isfile(source):
            with open(source, "rb") as f:
                return f.read()
        try:
            return base64.b64decode(source, validate=True)
        except Exception:
            return source.encode("utf-8")
    raise TypeError("Unsupported document source type")


def _bbox_to_tuple(bbox: Dict[str, Any]) -> Optional[Dict[str, float]]:
    if not bbox:
        return None
    return {
        "left": float(bbox.get("Left", 0.0)),
        "top": float(bbox.get("Top", 0.0)),
        "width": float(bbox.get("Width", 0.0)),
        "height": float(bbox.get("Height", 0.0)),
    }


def _cell_to_dict(cell: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "row_index": cell.get("RowIndex"),
        "column_index": cell.get("ColumnIndex"),
        "row_span": cell.get("RowSpan", 1),
        "column_span": cell.get("ColumnSpan", 1),
        "text": cell.get("Text", ""),
        "confidence": cell.get("Confidence"),
        "bbox": _bbox_to_tuple(cell.get("Geometry", {}).get("BoundingBox", {})),
        "is_header": bool(cell.get("EntityTypes") and "COLUMN_HEADER" in cell.get("EntityTypes", [])),
    }


def _extract_tables(textract_response: Dict[str, Any]) -> List[Dict[str, Any]]:
    blocks = textract_response.get("Blocks", [])
    block_map = {b["Id"]: b for b in blocks if "Id" in b}

    tables: List[Dict[str, Any]] = []
    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table = {
            "id": block.get("Id"),
            "confidence": block.get("Confidence"),
            "bbox": _bbox_to_tuple(block.get("Geometry", {}).get("BoundingBox", {})),
            "row_count": 0,
            "column_count": 0,
            "rows": [],
            "cells": [],
        }

        cell_blocks: List[Dict[str, Any]] = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                for child_id in rel.get("Ids", []):
                    child = block_map.get(child_id)
                    if child and child.get("BlockType") == "CELL":
                        cell_blocks.append(child)

        grid: Dict[int, Dict[int, Dict[str, Any]]] = {}
        max_row = 0
        max_col = 0

        for cell in cell_blocks:
            row = int(cell.get("RowIndex", 0))
            col = int(cell.get("ColumnIndex", 0))
            max_row = max(max_row, row + int(cell.get("RowSpan", 1)) - 1)
            max_col = max(max_col, col + int(cell.get("ColumnSpan", 1)) - 1)

            text_parts = []
            for rel in cell.get("Relationships", []):
                if rel.get("Type") == "CHILD":
                    for child_id in rel.get("Ids", []):
                        word = block_map.get(child_id)
                        if word and word.get("BlockType") in {"WORD", "SELECTION_ELEMENT"}:
                            if word.get("BlockType") == "WORD":
                                text_parts.append(word.get("Text", ""))
                            elif word.get("BlockType") == "SELECTION_ELEMENT":
                                text_parts.append("X" if word.get("SelectionStatus") == "SELECTED" else "")

            cell_dict = _cell_to_dict(
                {
                    "RowIndex": row,
                    "ColumnIndex": col,
                    "RowSpan": cell.get("RowSpan", 1),
                    "ColumnSpan": cell.get("ColumnSpan", 1),
                    "Text": " ".join(t for t in text_parts if t).strip(),
                    "Confidence": cell.get("Confidence"),
                    "Geometry": cell.get("Geometry", {}),
                    "EntityTypes": cell.get("EntityTypes", []),
                }
            )

            table["cells"].append(cell_dict)
            for r in range(row, row + int(cell.get("RowSpan", 1))):
                grid.setdefault(r, {})
                for c in range(col, col + int(cell.get("ColumnSpan", 1))):
                    grid[r][c] = cell_dict

        table["row_count"] = max_row
        table["column_count"] = max_col

        for r in range(1, max_row + 1):
            row_cells = []
            for c in range(1, max_col + 1):
                row_cells.append(grid.get(r, {}).get(c))
            table["rows"].append(
                {
                    "row_index": r,
                    "cells": row_cells,
                }
            )

        tables.append(table)

    return tables


def extract_table_cells_and_rows(
    document_source: Any,
    *,
    aws_region: Optional[str] = None,
    use_analyze_document: bool = True,
) -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Args:
        document_source: File path, raw bytes, or base64-encoded string.
        aws_region: AWS region for Textract, defaults to AWS_REGION/AWS_DEFAULT_REGION/us-east-1.
        use_analyze_document: If True uses analyze_document with TABLES; otherwise falls back to detect_document_text.

    Returns:
        Dictionary with tables, cells, and row structure.
    """
    region = aws_region or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    client = boto3.client("textract", region_name=region)

    document_bytes = _load_document_bytes(document_source)
    textract_response: Dict[str, Any]

    if use_analyze_document:
        textract_response = client.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["TABLES"],
        )
    else:
        textract_response = client.detect_document_text(
            Document={"Bytes": document_bytes}
        )

    tables = _extract_tables(textract_response)

    return {
        "provider": "amazon-textract",
        "region": region,
        "table_count": len(tables),
        "tables": tables,
        "raw_response": textract_response,
    }
